// One anonymous client id per execution. Veida meters the free tier per
// client id (and per IP per day), so a fresh id keeps each run independent.
const anonId = 'n8n-' + Math.random().toString(36).slice(2, 12);

return [{
  json: {
    anonId,
    prompt: $input.first().json['Prompt'],
    aspectRatio: $input.first().json['Aspect ratio'] || '1:1',
  },
}];
